using System.Security.Claims;using System.Text.Json;using HealthTracker.Api.Contracts;using HealthTracker.Api.Data;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;namespace HealthTracker.Api.Controllers;[Authorize][ApiController][Route("api/patient")]public class PatientController(AppDbContext db):ControllerBase{Guid U=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);[HttpGet]public async Task<IActionResult> Get(){var p=await db.Patients.SingleAsync(x=>x.UserId==U);return Ok(new{p.Id,p.Name,p.Dob,Conditions=JsonSerializer.Deserialize<List<string>>(p.ConditionsJson)??[],p.Notes,p.Relationship});}[HttpGet("all")]public async Task<IActionResult> All(){var ids=await AccessibleUsers();var rows=await db.Patients.Where(x=>ids.Contains(x.UserId)).Join(db.Users,p=>p.UserId,u=>u.Id,(p,u)=>new{p,u}).ToListAsync();return Ok(rows.Select(x=>new{x.p.Id,x.p.UserId,x.p.Name,x.p.Dob,Conditions=JsonSerializer.Deserialize<List<string>>(x.p.ConditionsJson)??[],x.p.Notes,x.p.Relationship,OwnerName=x.u.DisplayName,OwnerEmail=x.u.Email}));}
[HttpPut]public async Task<IActionResult> Put(PatientRequest r){var p=await db.Patients.SingleAsync(x=>x.UserId==U);p.Name=r.Name.Trim();p.Dob=string.IsNullOrWhiteSpace(r.Dob)?null:DateOnly.Parse(r.Dob);p.ConditionsJson=JsonSerializer.Serialize(r.Conditions);p.Notes=r.Notes;p.Relationship=r.Relationship;await db.SaveChangesAsync();return Ok(new{p.Id,p.Name,p.Dob,Conditions=r.Conditions,p.Notes,p.Relationship});}async Task<List<Guid>> AccessibleUsers(){var ids=await db.FamilyMembers.Where(x=>x.UserId==U&&x.Status=="approved").Join(db.FamilyMembers,a=>a.FamilyId,b=>b.FamilyId,(a,b)=>b.UserId).Distinct().ToListAsync();if(!ids.Contains(U))ids.Add(U);return ids;}}